units.example:
module beginner01(input logic a,b,s, output logic y);
  assign y = (s & b) | (~s & a);
endmodule

test.testbench:
module tb_beginner01;
 logic a,b,s,y; beginner01 dut(.a(a),.b(b),.s(s),.y(y));
 initial begin
  for(int v=0;v<8;v++)begin {s,b,a}=v[2:0];#1;if(y!==(s?b:a))$fatal(1,"mux mismatch %0d",v);end
  $display("beginner01 PASS");$finish;
 end
endmodule

units.example:
module beginner02(input logic [3:0] a,b, output logic [4:0] sum);
 assign sum = {1'b0,a} + {1'b0,b};
endmodule

test.testbench:
module tb_beginner02;
 logic [3:0] a,b;logic [4:0] sum;beginner02 dut(.a(a),.b(b),.sum(sum));
 initial begin for(int x=0;x<16;x++)for(int y=0;y<16;y++)begin a=x;b=y;#1;if(sum!==x+y)$fatal(1,"sum mismatch %0d+%0d",x,y);end $display("beginner02 PASS");$finish;end
endmodule

units.example:
module beginner03(input logic [1:0] sel,input logic [3:0] d0,d1,d2,d3,output logic [3:0] y);
 always_comb begin
  y=4'b0000;
  case(sel)
   2'd0:y=d0; 2'd1:y=d1; 2'd2:y=d2; 2'd3:y=d3;
   default:y=4'b0000;
  endcase
 end
endmodule

test.testbench:
module tb_beginner03;
 logic [1:0] sel;logic [3:0] d0,d1,d2,d3,y,e;beginner03 dut(.sel(sel),.d0(d0),.d1(d1),.d2(d2),.d3(d3),.y(y));
 initial begin d0=3;d1=6;d2=9;d3=12;for(int i=0;i<4;i++)begin sel=i;#1;case(i)0:e=d0;1:e=d1;2:e=d2;default:e=d3;endcase if(y!==e)$fatal(1,"select %0d mismatch",i);end $display("beginner03 PASS");$finish;end
endmodule

units.example:
module beginner04(input logic [3:0] a,b,input logic [1:0] op,output logic [4:0] result);
 always_comb begin result=5'd0;case(op)
  2'd0:result={1'b0,a}+{1'b0,b}; 2'd1:result={1'b0,a}-{1'b0,b};
  2'd2:result={1'b0,(a & b)}; 2'd3:result={1'b0,(a ^ b)};
  default:result=5'd0;endcase end
endmodule

test.testbench:
module tb_beginner04;
 logic [3:0] a,b;logic [1:0] op;logic [4:0] result;beginner04 dut(.a(a),.b(b),.op(op),.result(result));
 task automatic check(input logic [4:0] e);#1;if(result!==e)$fatal(1,"op=%0d a=%0d b=%0d got=%0d exp=%0d",op,a,b,result,e);endtask
 initial begin a=15;b=1;op=0;check(16);a=9;b=3;op=1;check(6);a=10;b=12;op=2;check(8);a=10;b=12;op=3;check(6);$display("beginner04 PASS");$finish;end
endmodule

units.example:
module beginner05(input logic clk,rst,en,d,output logic q);
 always_ff @(posedge clk) begin
  if(rst) q<=1'b0;
  else if(en) q<=d;
 end
endmodule

test.testbench:
module tb_beginner05;
 logic clk=0,rst=0,en=0,d=0,q;beginner05 dut(.clk(clk),.rst(rst),.en(en),.d(d),.q(q));always #5 clk=~clk;
 initial begin rst=1;@(posedge clk);#1;if(q!==0)$fatal(1,"reset failed");rst=0;en=1;d=1;@(posedge clk);#1;if(q!==1)$fatal(1,"capture failed");en=0;d=0;@(posedge clk);#1;if(q!==1)$fatal(1,"hold failed");$display("beginner05 PASS");$finish;end
endmodule

units.example:
module beginner06(input logic clk,clear,en,output logic [3:0] count);
 always_ff @(posedge clk) begin
  if(clear) count<=4'd0;
  else if(en) count<=count+4'd1;
 end
endmodule

test.testbench:
module tb_beginner06;
 logic clk=0,clear=0,en=0;logic [3:0] count;beginner06 dut(.clk(clk),.clear(clear),.en(en),.count(count));always #5 clk=~clk;
 task automatic tick;@(posedge clk);#1;endtask
 initial begin clear=1;tick();if(count!==0)$fatal(1,"clear");clear=0;en=1;tick();if(count!==1)$fatal(1,"increment");en=0;tick();if(count!==1)$fatal(1,"hold");en=1;repeat(14)tick();if(count!==15)$fatal(1,"count to 15");tick();if(count!==0)$fatal(1,"wrap");$display("beginner06 PASS");$finish;end
endmodule

units.example:
module beginner07(input logic clk,rst,bit_in,output logic pulse);
 typedef enum logic {IDLE,SEEN_ONE} state_t;state_t state,next_state;
 always_ff @(posedge clk) if(rst)state<=IDLE;else state<=next_state;
 always_comb begin next_state=state;pulse=1'b0;case(state)
  IDLE:if(bit_in)next_state=SEEN_ONE;
  SEEN_ONE:if(bit_in)begin pulse=1'b1;next_state=SEEN_ONE;end else next_state=IDLE;
  default:next_state=IDLE;endcase end
endmodule

test.testbench:
module tb_beginner07;
 logic clk=0,rst=0,bit_in=0,pulse;beginner07 dut(.clk(clk),.rst(rst),.bit_in(bit_in),.pulse(pulse));always #5 clk=~clk;
 task automatic sample(input logic value,input logic expected);@(negedge clk);bit_in=value;#1;if(pulse!==expected)$fatal(1,"output mismatch");@(posedge clk);#1;endtask
 initial begin rst=1;@(posedge clk);#1;rst=0;sample(1,0);sample(1,1);sample(0,0);sample(1,0);sample(1,1);$display("beginner07 PASS");$finish;end
endmodule

units.example:
module beginner08(input logic [1:0] a,b,output logic eq);
 assign eq=(a==b);
endmodule

test.testbench:
module tb_beginner08;
 logic [1:0] a,b;logic eq;beginner08 dut(.a(a),.b(b),.eq(eq));
 initial begin for(int x=0;x<4;x++)for(int y=0;y<4;y++)begin a=x;b=y;#1;if(eq!==(x==y))$fatal(1,"a=%0d b=%0d eq=%b",a,b,eq);end $display("beginner08 PASS");$finish;end
endmodule

units.example:
module beginner09(input logic [2:0] data,output logic parity);
