units.example:
module beginner10 #(parameter int WIDTH=4)(input logic clk,rst,en,output logic [WIDTH-1:0] count);
 always_ff @(posedge clk) begin
  if(rst) count<='0;
  else if(en) count<=count+1'b1;
 end
endmodule

test.testbench:
module tb_beginner10;
 logic clk=0,rst=0,en=0;logic [2:0] count;beginner10 #(.WIDTH(3)) dut(.clk(clk),.rst(rst),.en(en),.count(count));always #5 clk=~clk;
 task automatic tick;@(posedge clk);#1;endtask
 initial begin rst=1;tick();if(count!==0)$fatal(1,"reset");rst=0;en=1;repeat(7)tick();if(count!==7)$fatal(1,"count");tick();if(count!==0)$fatal(1,"wrap");en=0;tick();if(count!==0)$fatal(1,"hold");$display("beginner10 PASS");$finish;end
endmodule
